from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import CommercialContract
from .serializers import ContractSerializer

class CommercialContractViewSet(viewsets.ModelViewSet):
    serializer_class = ContractSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return CommercialContract.objects.filter(company=self.request.user.company)

    @action(detail=True, methods=["post"])
    def sign(self, request, pk=None):
        contract = self.get_object()
        contract.is_signed = True
        contract.signed_by = request.user
        contract.save()
        return Response({"status": "contract_signed", "contract_id": contract.id})
